CREATE TABLE client(
    id_client NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    prénom VARCHAR2(100) NOT NULL,
    nom VARCHAR2(100) NOT NULL,
    date_naissance DATE DEFAULT SYSDATE NOT NULL,
    email VARCHAR2(100)
);
