CREATE TABLE avion (
    "ID_AVION" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY START WITH 1 INCREMENT BY 1 NOT NULL, 
    "COULEUR" VARCHAR2(100 BYTE) DEFAULT 'Blanc', 
    "MODÈLE" VARCHAR2(100 BYTE) NOT NULL, 
    "COMPAGNIE" VARCHAR2(100 BYTE) NOT NULL, 
    PRIMARY KEY ("ID_AVION")
);


