CREATE TABLE destination (
    "CODE_IATA"            VARCHAR2(3 BYTE) NOT NULL, 
    "PAYS"                 VARCHAR2(100 BYTE) NOT NULL, 
    "CAPACITÉ"             NUMBER, 
    "IMAGE_DE_DESTINATION" VARCHAR2(100 BYTE) NOT NULL, 
    "EN_FEU"               BOOLEAN NOT NULL, 
    "VILLE"                VARCHAR2(255 BYTE) DEFAULT 'Inconnue' NOT NULL, 
    
    
    PRIMARY KEY ("CODE_IATA")
);


