CREATE TABLE billet (
    "ID_BILLET" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY START WITH 1 INCREMENT BY 1 NOT NULL, 
    "ID_CLIENT" NUMBER NOT NULL, 
    "ID_VOL" NUMBER NOT NULL, 
    "CLASSE" VARCHAR2(100 BYTE) NOT NULL, 
    "PRIX" NUMBER(10,2) NOT NULL, 
    "DATE_CRÉÉ" DATE DEFAULT SYSDATE NOT NULL, 
    "DATE_DÉPART" DATE NOT NULL, 
    "DATE_ARRIVÉ" DATE NOT NULL, 
    "HEURE_DÉPART" VARCHAR2(100 BYTE), 
    "HEURE_ARRIVÉE" VARCHAR2(100 BYTE), 
    
    
    PRIMARY KEY ("ID_BILLET"),
    
    
    CONSTRAINT "FK_CLIENT" FOREIGN KEY ("ID_CLIENT") REFERENCES client("ID_CLIENT"), 
    CONSTRAINT "FK_VOL" FOREIGN KEY ("ID_VOL") REFERENCES vol("ID_VOL")
);



CREATE TABLE vol (
    "ID_VOL"                NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY START WITH 1 INCREMENT BY 1 NOT NULL, 
    "ID_AVION"              NUMBER NOT NULL, 
    "CODE_IATA_DÉPART"      VARCHAR2(3 BYTE) NOT NULL, 
    "CODE_IATA_DESTINATION" VARCHAR2(3 BYTE) NOT NULL, 
    "DURÉE_DE_VOL"          INTERVAL DAY (2) TO SECOND (6), 
    "CARBURANT_CONSOMMER"   NUMBER(10,2), 
    "PRIX"                  NUMBER NOT NULL, 
    "TRANSFER"              NUMBER DEFAULT 0 NOT NULL, 
    
    -- Clé primaire
    PRIMARY KEY ("ID_VOL"),
    
   
    CONSTRAINT "FK_AVION" FOREIGN KEY ("ID_AVION") REFERENCES avion("ID_AVION"), 
    CONSTRAINT "FK_DÉPART" FOREIGN KEY ("CODE_IATA_DÉPART") REFERENCES départ("CODE_IATA"), 
    CONSTRAINT "FK_DESTINATION" FOREIGN KEY ("CODE_IATA_DESTINATION") REFERENCES destination("CODE_IATA")
);


